def install_meeting_catalog(apps, schema_editor):
    db = schema_editor.connection.alias
    phases = apps.get_model('fellows', 'Phase').objects.using(db)
    cohorts = apps.get_model('fellows', 'Cohort').objects.using(db)
    phase_mapping = (
        ('Launchpad', 'Design Thinking', ('Orbit of Ideas',)),
        ('Lift-off', 'Guided Collaboration', ('Launch Sequence', 'Mission Build')),
        ('Orbit', 'Enduring Impact', ('Trajectory', 'Touchdown', 'Graduation')),
    )
    for order, (name, description, previous) in enumerate(phase_mapping, 1):
        phase, _ = phases.update_or_create(name=f'Phase {order}: {name}', defaults={
            'order': order, 'description': description,
        })
        old = phases.filter(name__in=(*previous, name))
        cohorts.filter(phase_id__in=old).update(phase_id=phase.pk)
        old.delete()

    badges = apps.get_model('fellows', 'Badge').objects.using(db)
    badges.all().delete()  # Cascades to FellowBadge only.
    apps.get_model('fellows', 'Fellow').objects.using(db).update(xp_points=0)
    for order, (name, description, artwork) in enumerate(MILESTONES, 1):
        badges.create(name=name, slug=slugify(name), order=order, description=description,
                      artwork=artwork, trigger_type='manual', xp_reward=100)

    tasks = apps.get_model('fellows', 'Task').objects.using(db)
    for task in tasks.filter(availability_request__isnull=False, title__istartswith='When2meet:').iterator():
        tasks.filter(pk=task.pk).update(title='WhenBound:' + task.title.split(':', 1)[1])


